function createWorkSupport(api){
  const M=WorkSupportModel,e=api.esc,$=s=>document.querySelector(s),names={prompt:'提示词',skill:'Skill',agent:'Agent'};
  let previewContext=null;
  const find=(type,id)=>api.getState()[type==='task'?'tasks':'projects'].find(x=>x.id===id);
  function dialog(id,title){let el=document.getElementById(id);if(!el){el=document.createElement('dialog');el.id=id;el.className='work-support-dialog';document.body.append(el);}el.setAttribute('aria-label',title);return el;}
  function head(title,id){return `<div class="dialog-head"><h2>${e(title)}</h2><button type="button" class="close" data-work-close="${id}" aria-label="关闭${e(title)}">×</button></div>`;}
  function replyButton(t){return t.status==='waiting'&&!t.done?`<button type="button" class="text-button" data-work-reply="${e(t.id)}">收到回复</button>`:'';}
  function toolsButton(type,record){const count=M.linkedTools(api.getState(),type,record).length;return count?`<button type="button" class="text-button" data-work-tools="${type}:${e(record.id)}">常用工具 · ${count}</button>`:'';}
  function picker(type,record){
    const state=api.getState(),selected=new Set(record.toolRefs||[]),all=M.tools(state,['prompt','skill','agent'].flatMap(k=>(state[{prompt:'prompts',skill:'skills',agent:'agents'}[k]]||[]).map(t=>k+':'+t.id)));
    const parent=type==='task'?state.projects.find(p=>p.id===record.projectId):null,inherited=M.tools(state,parent?.toolRefs);
    return `<details class="editor-options work-tool-picker"><summary>常用工具 <span class="meta">${selected.size?'已关联 '+selected.size+' 个':'选填'}</span></summary><div class="editor-options-body"><p class="meta">关联后，可在${type==='task'?'任务':'项目'}中使用。提示词可带入项目和任务背景。</p><p class="meta" data-work-inherited ${inherited.length?'':'hidden'}>项目常用：${inherited.map(t=>e(t.item.title)).join('、')}</p><input type="search" data-work-tool-search aria-label="搜索可关联的工具" placeholder="搜索提示词、Skill 或 Agent"><div class="work-tool-options">${all.map(x=>`<div class="work-tool-option" data-tool-search="${e((x.item.title+' '+names[x.kind]+' '+(x.item.category||'')).toLowerCase())}"><label><input type="checkbox" name="toolRefs" value="${e(x.key)}" ${selected.has(x.key)?'checked':''}><span><strong>${e(x.item.title)}</strong><small>${names[x.kind]} · ${e(x.item.category||'未分类')}</small></span></label><button type="button" class="text-button" data-work-use="${e(x.key)}" data-work-editor>试用</button></div>`).join('')||'<p class="meta">先在知识典藏收藏工具，再到这里关联。</p>'}</div><p class="meta work-tool-no-results" hidden>没有匹配的工具。</p></div></details>`;
  }
  function history(record){const list=record.replyHistory||[],source=api.getState().tasks.find(t=>t.id===record.sourceTaskId);return `${source?`<p class="meta">来自任务：${e(source.title)}</p>`:''}${list.length?`<details class="editor-options"><summary>回复记录 · ${list.length}</summary><div class="editor-options-body work-reply-history">${[...list].reverse().map(r=>`<article><small>${e(r.at?.slice(0,10))} · ${e(r.waitingFor||'对方')}</small><p>${e(r.waitingReason||'收到回复')}</p>${r.note?`<p>${e(r.note)}</p>`:''}<small>${({resume:'继续处理原任务',next:'已衔接下一步',done:'已完成'})[r.action]||''}${r.nextTaskId?' · '+e(api.getState().tasks.find(t=>t.id===r.nextTaskId)?.title||'后续任务已移除'):''}</small></article>`).join('')}</div></details>`:''}`;}
  function continuation(project){
    if(project.status==='done')return '';const c=M.continuation(api.getState(),project),module=c.module;if(!c.task&&!project.next)return '';
    return `<section class="project-continue ${!c.docs.length&&!c.waiting.length?'is-simple':''}" aria-label="继续推进"><div class="continue-main"><span class="eyebrow">继续推进${module?' · '+e(module.title):''}</span>${c.task?`<button class="continue-title" data-edit="task:${e(c.task.id)}">${e(c.task.title)}</button><p class="meta">${c.explicit?'你指定的下一步':'建议下一步'}${c.task.status==='waiting'?' · 等待 '+e(c.task.waitingFor||'对方'):c.task.plannedDate?' · 计划 '+e(c.task.plannedDate):' · 尚未安排日期'}</p><div class="continue-actions"><button class="text-button" data-work-next="${e(project.id)}">指定下一步</button>${replyButton(c.task)}${toolsButton('task',c.task)}<button class="text-button" data-source-project="${e(project.id)}" data-source-stage="${e(module?.id||'__unassigned')}">进入模块 →</button></div>`:`<h2>${project.next?e(project.next):'确定一件接下来要做的事'}</h2><div class="continue-actions">${module?`<button class="text-button" data-work-new="${e(project.id)}" data-work-module="${e(module.id)}">＋ 添加下一步任务</button>`:'<button class="text-button" data-add-module>＋ 建立项目模块</button>'}${toolsButton('project',project)}</div>`}</div><div class="continue-context">${c.waiting.length?`<div><small>等待回应 · ${c.waiting.length}</small>${c.waiting.slice(0,2).map(t=>`<button class="continue-wait" data-edit="task:${e(t.id)}">${e(t.waitingFor||'对方')} · ${e(t.waitingReason||t.title)}<span>${t.followUp?'跟进 '+e(t.followUp):'未设跟进日期'}</span></button>`).join('')}</div>`:''}${c.docs.length?`<div class="continue-docs"><small>相关文档</small>${c.docs.slice(0,3).map(n=>api.documentOpen(n,n.title)).join('')}${c.docs.length>3?'<button class="text-button" data-project-tab="materials">全部相关文档 →</button>':''}</div>`:''}</div></section>`;
  }
  function openReply(id){
    if(!api.canLeaveEditor())return api.toast('请先保存当前任务修改，再处理回复。');
    const task=find('task',id);if(!task||task.done||task.status!=='waiting')return api.toast('这项任务已不在等待回复');
    const el=dialog('work-reply-dialog','处理回复');el.innerHTML=`<form>${head('处理回复',el.id)}<p class="work-dialog-context">${e(task.title)}</p><p class="meta">等待 ${e(task.waitingFor||'对方')}${task.waitingReason?' · '+e(task.waitingReason):''}</p><label class="field">回复要点（选填）<textarea name="note" placeholder="记录收到的结论，方便以后回查"></textarea></label><label class="field">接下来<select name="action"><option value="resume">继续处理这项任务</option><option value="next">完成当前事项，创建下一步</option><option value="done">这件事已经完成</option></select></label><label class="field" data-next-title hidden>下一步任务<input name="title" maxlength="300"></label><label class="field" data-reply-date>计划处理日期<input name="plannedDate" type="date" value="${api.today()}"><small class="meta">可留空，稍后再安排；原任务截止日期不变。</small></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" class="button" data-work-close="${el.id}">取消</button><button class="button primary">确认处理</button></div></form>`;
    const form=el.querySelector('form');form.elements.action.onchange=()=>{const value=form.elements.action.value;form.querySelector('[data-next-title]').hidden=value!=='next';form.elements.title.required=value==='next';form.querySelector('[data-reply-date]').hidden=value==='done';form.elements.plannedDate.disabled=value==='done';};
    form.onsubmit=ev=>{ev.preventDefault();const data=Object.fromEntries(new FormData(form));let result;try{M.reply(JSON.parse(JSON.stringify(api.getState())),id,data,'validation-id');}catch(err){form.querySelector('[role=alert]').textContent=err.message;return;}
      if(api.commit(next=>{result=M.reply(next,id,data,api.uid());api.sync(next);})){el.close();$('#editor').close();api.refresh();api.toast(result.next?'已完成等待事项，并创建下一步任务':result.task.done?'已记录回复并完成任务':'已记录回复，任务恢复为待处理');}else form.querySelector('[role=alert]').textContent='保存失败，输入内容已保留，请重试。';};el.showModal();
  }
  function openTools(type,id){
    const record=find(type,id);if(!record)return api.toast('记录已不存在');previewContext={type,record};const list=M.linkedTools(api.getState(),type,record),el=dialog('work-tools-dialog','常用工具');
    el.innerHTML=`${head('常用工具',el.id)}<p class="work-dialog-context">${e(record.title)}</p><div class="work-tool-options">${list.map(x=>`<div class="work-tool-option"><span><strong>${e(x.item.title)}</strong><small>${names[x.kind]}${!(record.toolRefs||[]).includes(x.key)?' · 项目常用':''}</small></span><button type="button" class="button soft" data-work-use="${e(x.key)}">${x.kind==='agent'?'访问':x.kind==='skill'?'调用':'使用'}</button></div>`).join('')||'<p class="meta">还没有关联工具。</p>'}</div><div class="dialog-actions"><button class="button" data-work-configure="${type}:${e(id)}">管理关联</button></div>`;el.showModal();
  }
  async function useTool(key,fromEditor){
    const found=M.tools(api.getState(),[key])[0];if(!found)return api.toast('这项收藏已移除');
    const context=fromEditor?api.editorRecord():previewContext;if(!context)return;
    if(found.kind==='agent'){let url;try{url=AgentModel.link(found.item.url);}catch(err){return api.toast(err.message);}window.open(url,'_blank','noopener,noreferrer');return;}
    if(found.kind==='skill'){try{await navigator.clipboard.writeText(SkillModel.invocation(found.item));api.toast('已复制 Skill 调用内容；请在支持该 Skill 的 AI 中使用');return;}catch{}}
    const text=found.kind==='skill'?SkillModel.invocation(found.item):M.prompt(api.getState(),context.type,context.record,found.item.body),el=dialog('work-use-dialog',found.kind==='skill'?'调用 Skill':'使用提示词');
    el.innerHTML=`${head(found.kind==='skill'?'调用 Skill':'使用提示词',el.id)}<p class="work-dialog-context">${e(found.item.title)}</p><p class="meta">${found.kind==='skill'?'复制调用内容后，粘贴到已支持或已安装此 Skill 的 AI 工具中。':'已带入可用的工作背景。缺失的变量保留原样，可修改后使用。'}</p><label class="field">${found.kind==='skill'?'调用内容':'提示词与工作背景'}<textarea class="work-prompt-preview" aria-label="使用内容">${e(text)}</textarea></label><p class="error" role="alert"></p><div class="dialog-actions"><button class="button primary" data-work-copy>复制${found.kind==='skill'?'调用内容':'内容'}</button>${found.kind==='prompt'&&api.smart()&&!$('#editor').open?'<button class="button" data-work-ai>交给助理</button>':''}</div>`;el.showModal();
  }
  document.addEventListener('input',ev=>{if(!ev.target.matches('[data-work-tool-search]'))return;const picker=ev.target.closest('.work-tool-picker'),q=ev.target.value.trim().toLowerCase();let count=0;picker.querySelectorAll('[data-tool-search]').forEach(row=>{row.hidden=!row.dataset.toolSearch.includes(q);if(!row.hidden)count++;});picker.querySelector('.work-tool-no-results').hidden=count>0;});
  document.addEventListener('change',ev=>{if(ev.target.name==='projectId'){const row=$('[data-work-inherited]');if(row){const parent=api.getState().projects.find(p=>p.id===ev.target.value),list=M.tools(api.getState(),parent?.toolRefs);row.hidden=!list.length;row.textContent='项目常用：'+list.map(x=>x.item.title).join('、');}}if(ev.target.name==='toolRefs'){const picker=ev.target.closest('.work-tool-picker');picker.querySelector('summary .meta').textContent='已关联 '+picker.querySelectorAll('input[type=checkbox]:checked').length+' 个';}});
  document.addEventListener('click',async ev=>{
    const close=ev.target.closest('[data-work-close]');if(close){document.getElementById(close.dataset.workClose)?.close();return;}
    const reply=ev.target.closest('[data-work-reply]');if(reply){openReply(reply.dataset.workReply);return;}
    const tools=ev.target.closest('[data-work-tools]');if(tools){const [type,id]=tools.dataset.workTools.split(':');openTools(type,id);return;}
    const configure=ev.target.closest('[data-work-configure]');if(configure){const [type,id]=configure.dataset.workConfigure.split(':');$('#work-tools-dialog').close();api.edit(type,id);$('.work-tool-picker').open=true;return;}
    const next=ev.target.closest('[data-work-next]');if(next){api.edit('project',next.dataset.workNext);const select=$('#form-fields [name=nextTaskId]');select.closest('details').open=true;select.focus();return;}
    const create=ev.target.closest('[data-work-new]');if(create){api.edit('task',null,{projectId:create.dataset.workNew,moduleId:create.dataset.workModule});return;}
    const use=ev.target.closest('[data-work-use]');if(use){useTool(use.dataset.workUse,use.hasAttribute('data-work-editor'));return;}
    if(ev.target.closest('[data-work-copy]')){try{await navigator.clipboard.writeText($('#work-use-dialog textarea').value);api.toast('已复制');}catch{$('#work-use-dialog textarea').select();$('#work-use-dialog [role=alert]').textContent='无法直接复制，请复制上方已选中的内容。';}return;}
    if(ev.target.closest('[data-work-ai]')){const text=$('#work-use-dialog textarea').value;if(api.compose(text)){ $('#work-use-dialog').close();$('#work-tools-dialog')?.close();}}
  });
  return {picker,history,replyButton,toolsButton,continuation};
}
